import { PersonColumnHeads, PersonColumns } from '../../slots/defs/personColumns';
import { type Person } from '../people/people';
import { useSplit } from '../rates/split.slot';
import { useOverdue } from '../overdue/overdue.slot';
import { useSettings } from '../settings/settings';
import { useCurrentSheet } from '../../session/session';

// A person's score: their settled-total divided by 100, minus 5 for every overdue claim of theirs that counts,
// rounded half to even to a whole number.
function ScoreHead() {
  return <th>Score</th>;
}

/** The score from a settled-total (a 2-place figure) and an overdue count. */
export function score(settled: string, overdue: number): string {
  const [whole, frac = ''] = settled.replace('-', '').split('.');
  const sign = settled.startsWith('-') ? -1n : 1n;
  // In ten-thousandths of a point: settled (in hundredths) less 5 points per overdue claim.
  const n = sign * BigInt(whole + frac.padEnd(2, '0').slice(0, 2)) - BigInt(overdue) * 50000n;
  const q = n / 10000n;
  const r = n % 10000n;
  const twice = 2n * (r < 0n ? -r : r);
  const step = n < 0n ? -1n : 1n;
  const rounded = twice > 10000n || (twice === 10000n && q % 2n !== 0n) ? q + step : q;
  return rounded.toString();
}

function PersonScore({ person }: { person: Person }) {
  const { settled } = useSplit()(person);
  const { count } = useOverdue()(person);
  return <td data-testid="person-score">{score(settled, count)}</td>;
}

function BandHead() {
  return <th>Band</th>;
}

/** A person's band from their score: HIGH at or above the high threshold, MID at or above the mid one, else LOW;
 *  blank while either threshold is. */
export function band(score: string, mid: string | null | undefined, high: string | null | undefined): string {
  if (mid == null || high == null) return '';
  const s = BigInt(score);
  return s >= BigInt(high) ? 'HIGH' : s >= BigInt(mid) ? 'MID' : 'LOW';
}

function PersonBand({ person }: { person: Person }) {
  const [sheet] = useCurrentSheet();
  const settings = useSettings(sheet);
  const { settled } = useSplit()(person);
  const { count } = useOverdue()(person);
  return <td data-testid="person-band">{band(score(settled, count), settings.data?.scoreMid, settings.data?.scoreHigh)}</td>;
}

export const contributions = [
  PersonColumnHeads.fill({ order: 17.2, Component: ScoreHead }),
  PersonColumns.fill({ order: 17.2, Component: PersonScore }),
  PersonColumnHeads.fill({ order: 17.3, Component: BandHead }),
  PersonColumns.fill({ order: 17.3, Component: PersonBand }),
];
package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.ClaimStore;
import net.officefloor.hq.app.person.PersonStore;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Stores the sheet's today; a new today releases every claim's lock (each open editor's). Before a new today
 *  takes effect, each person's due-total as it stood on the day being left is recorded, in list order, as
 *  SNAPSHOT sheet=<id> by=<user> name=<name> due-total=<due-total>, and kept on the person with that day. */
public class SaveToday {
    public void save(@PathVariable("sheetId") String sheetId, @Val LocalDate today, @Val TodayRequest request,
            @Val Rollup before, SheetStore store, ClaimStore claims, PersonStore people, Audit audit) {
        String id = sheetId.trim();
        LocalDate leaving = store.today(id);
        // The new today is stored first, so the snapshots are kept as made on it (a sheet read as of the day
        // being left does not show them yet).
        store.setToday(id, today);
        if (!today.equals(leaving)) {
            before.people().forEach((personId, figures) -> {
                people.snapshot(id, personId, leaving, figures.dueTotal());
                audit.record("SNAPSHOT sheet=" + id + " by=" + request.user() + " name=" + figures.name()
                        + " due-total=" + figures.dueTotal());
            });
            claims.unlockAll(id);
        }
    }
}
# POST /api/sheets/{sheetId}/today — set the sheet's today (body: {today: yyyy-MM-dd, user}).
# A date that does not parse is refused (400) and nothing is stored. A new today first records one
# SNAPSHOT line per person (their due-total on the day being left), then only the ROLLUP/TOTALS lines
# of the figures it moved. With grace days set, every
# open period whose to-date plus the grace days is before the new today is then closed (by to-date) as a
# close by hand would, each recorded as PERIOD_CLOSED ... auto=yes before the ROLLUP/TOTALS lines.
