import { dueTotal, personSplit, useRates } from './rates';
import { useFigure } from '../locale/locale';

// A person's settled-total and open-total (their due-total before the cap, split by status), and the
// sheet's: everyone's added up, not trimmed.
function SplitHead() {
  return (
    <>
      <th>Settled total</th>
      <th>Open total</th>
    </>
  );
}

export function useSplit() {
  const [sheet] = useCurrentSheet();
  const claims = useClaims(sheet);
  const rates = useRates(sheet);
  const today = useSheetToday(sheet);
  const settings = useSettings(sheet).data;
  return (person: Person) =>
    personSplit(
      live((claims.data ?? []).filter((c) => c.personId === person.id), [person]),
      rates.data,
      person.grades,
      today,
      floorOf(settings),
      lateOf(settings, today, [person]),
    );
}

function PersonSplit({ person }: { person: Person }) {
  const fig = useFigure();
  const { settled, open } = useSplit()(person);
  return (
    <>
      <td data-testid="person-settled-total">{fig(settled)}</td>
      <td data-testid="person-open-total">{fig(open)}</td>
    </>
  );
}

function SplitTotal() {
  const fig = useFigure();
  const [sheet] = useCurrentSheet();
  const people = usePeople(sheet);
  const figures = (people.data ?? []).map(useSplit());
  return (
    <p>
      Settled total <strong data-testid="rollup-settled-total">{fig(dueTotal(figures.map((f) => f.settled)))}</strong>{' '}
      Open total <strong data-testid="rollup-open-total">{fig(dueTotal(figures.map((f) => f.open)))}</strong>
    </p>
  );
}

export const contributions = [
  PersonColumnHeads.fill({ order: 15.2, Component: SplitHead }),
  PersonColumns.fill({ order: 15.2, Component: PersonSplit }),
  HomeMain.fill({ order: 35.5, Component: SplitTotal }),
];
import { HomeMain } from '../../slots/defs/homeMain';
import { PersonColumnHeads, PersonColumns } from '../../slots/defs/personColumns';
import { type Person, usePeople } from '../people/people';
import { useCurrentSheet } from '../../session/session';
import { useSheetToday } from '../sheet/sheet';
import { counts, live, useClaims } from '../claims/claims';
import { floorOf, useSettings } from '../settings/settings';
import { trimmedTotal, useRates } from '../rates/rates';
import { lateOf, overdueFigures } from './overdue';
import { useFigure } from '../locale/locale';
import { useColumnShown } from '../columns/columns';

// A person's overdue count and overdue-total (the due of their overdue claims that count), and the sheet's.
function OverdueHead() {
  const shown = useColumnShown();
  return (
    <>
      {shown('overdue-count') && <th>Overdue</th>}
      {shown('overdue-total') && <th>Overdue total</th>}
    </>
  );
}

/** A person's overdue figures on the sheet (the current sheet's unless another is named). */
export function useOverdue(of?: string) {
  const [current] = useCurrentSheet();
  const sheet = of ?? current;
  const claims = useClaims(sheet);
  const rates = useRates(sheet);
  const today = useSheetToday(sheet);
  const settings = useSettings(sheet).data;
  return (person: Person) =>
    overdueFigures(
      live((claims.data ?? []).filter((c) => c.personId === person.id), [person]).filter(counts),
      rates.data,
      person.grades,
      floorOf(settings),
      today,
      lateOf(settings, today, [person]),
    );
}

function PersonOverdue({ person }: { person: Person }) {
  const fig = useFigure();
  const { count, total } = useOverdue()(person);
  const shown = useColumnShown();
  return (
    <>
      {shown('overdue-count') && <td data-testid="person-overdue-count">{count}</td>}
      {shown('overdue-total') && <td data-testid="person-overdue-total">{fig(total)}</td>}
    </>
  );
}

/** The sheet's overdue figures (the current sheet's unless another is named): everyone's overdue counts
 *  added up, and their overdue-totals added up trimmed of the single highest and lowest when three or more
 *  people have one. */
export function useSheetOverdue(of?: string): { count: number; total: string } {
  const [current] = useCurrentSheet();
  const sheet = of ?? current;
  const people = usePeople(sheet);
  const figures = (people.data ?? []).map(useOverdue(sheet));
  return { count: figures.reduce((n, f) => n + f.count, 0), total: trimmedTotal(figures.map((f) => f.total)) };
}

function OverdueTotal() {
  const fig = useFigure();
  const { count, total } = useSheetOverdue();
  return (
    <p>
      Overdue <strong data-testid="rollup-overdue-count">{count}</strong>{' '}
      Overdue total <strong data-testid="rollup-overdue-total">{fig(total)}</strong>
    </p>
  );
}

export const contributions = [
  PersonColumnHeads.fill({ order: 17, Component: OverdueHead }),
  PersonColumns.fill({ order: 17, Component: PersonOverdue }),
  HomeMain.fill({ order: 36, Component: OverdueTotal }),
];

